package jp.tapmarker;
import java.io.*;import java.util.*;import java.util.zip.*;

/** Real video pixels, different scenes and translated individual controls. No device input. */
public final class Video6666ReplayTest {
 static final String P=ShoppingPreset.P;static int checks;static Map<String,float[]> refs;static Map<String,VirtualPresetProfileTest.Image> frames=new LinkedHashMap<>();
 static void check(boolean value,String why){checks++;if(!value)throw new AssertionError(why);}
 static void load()throws Exception{refs=VirtualPresetProfileTest.canonical("tests/video6666-references.bin");try(DataInputStream in=new DataInputStream(new GZIPInputStream(new FileInputStream("tests/video6666-replay.bin.gz")))){int n=in.readInt();for(int i=0;i<n;i++)frames.put(in.readUTF(),new VirtualPresetProfileTest.Image(in));check(in.read()==-1,"all video fixture bytes read");}}
 static class Runtime {
  PhaseEngine e=new PhaseEngine();ShoppingLayout layout;Map<String,float[]> last;
  Runtime(){check(ShoppingPreset.install(e,refs),"shopping graph installed");e=e.runtimeCopy();e.strictRuntime=true;layout=(ShoppingLayout)AdaptiveLayout.install(e,ShoppingPreset.APP,refs,Collections.emptyMap());check(layout!=null,"normal and virtual entry point select shopping layout");AdCloseAutomaton.install(e,ShoppingPreset.APP);check(e.validate().isEmpty(),"graph valid: "+e.validate());}
  Map<String,float[]> sample(String frame,long now){VirtualPresetProfileTest.Image im=frames.get(frame);last=layout.sample(e.activeRegions(),im.width,im.height,im,now);return last;}
  PhaseEngine.Watch event(String state,String first,String second){e.enter(P+state,0);e.observe(sample(first,1000),1000);check(e.poll()==null,"one frame cannot authorize transition "+state+" / "+first);e.observe(sample(second,1350),1350);return e.poll();}
  PhaseEngine.Watch expect(String state,String first,String second,String next,int action){PhaseEngine.Watch w=event(state,first,second);if(w==null){StringBuilder b=new StringBuilder();for(PhaseEngine.Watch rule:e.phases.get(e.current).watches)if(rule.condition==PhaseEngine.MATCH)b.append(rule.regionId).append('=').append(rule.distance(last.get(rule.regionId))).append('/').append(rule.threshold).append(' ');System.out.println("Scores: "+b);}check(w!=null&&w.nextPhase.equals(P+next)&&w.action==action,"branch "+state+" / "+first+" -> "+next+" actual="+(w==null?e.diagnostic:w.id));return w;}
  float[] point(PhaseEngine.Watch w,String frame){VirtualPresetProfileTest.Image im=frames.get(frame);return layout.point(w,last,im.width,im.height);}
 }
 static void scenes(){
  for(String state:new String[]{"check","verify","ad"})for(String[] row:new String[][]{{"2","42","shop"},{"88","123","shop"},{"124","153","main"},{"198","240","main"},{"63","95","stock"},{"103","103","stock"},{"4","6","shift"},{"120","120","summon"},{"176","176","boost"},{"43","89","arrival"},{"94","99","arrival"},{"137","208","missions"},{"141","207","missions"},{"152","152","reward"},{"139","206","clear"}}){Runtime r=new Runtime();r.expect(state,row[0],row[1],row[2],PhaseEngine.WAIT);check(RecoveryRequest.visibleBranch(r.e,r.last),"real game screen cancels delayed intent: "+row[1]);check(!ShoppingPreset.playable(r.e,r.last),"classifier/dialog states cannot start markers");}
 }
 static RegionSampler.Pixels sized(String frame,int w,int h){VirtualPresetProfileTest.Image im=frames.get(frame);return (x,y)->im.get(x*im.width/w,y*im.height/h);}
 static void shop(){
  Runtime r=new Runtime();PhaseEngine.Watch w=r.expect("shop","2","2","stock-opening",PhaseEngine.CENTER);float[] p=r.point(w,"2");check(p!=null&&p[0]/428>.72f&&p[0]/428<.85f&&p[1]/960>.37f&&p[1]/960<.40f,"tap this individual empty tray "+Arrays.toString(p));
  VirtualPresetProfileTest.Image im=frames.get("2-native");List<PhaseEngine.Region> plan=ScanPlan.select(r.e,w.regionId,false);check(plan.size()==2&&plan.get(1).id.equals(P+"shop"),"empty tray preflight includes its own shop dependency");Map<String,float[]> fresh=r.layout.sample(plan,im.width,im.height,im,2000);check(r.e.confirmsAction(w,r.e.current,r.e.epoch,fresh),"native empty tray preflight");fresh=r.layout.sample(plan,im.width,im.height,sized("3",im.width,im.height),2350);check(!r.e.confirmsAction(w,r.e.current,r.e.epoch,fresh)&&r.layout.point(w,fresh,im.width,im.height)==null,"dim shop cancels shelf tap");
  r=new Runtime();w=r.expect("stock","63","95","stock-wait",PhaseEngine.CENTER);p=r.point(w,"95");check(w.id.equals(P+"stock-meat")&&p!=null&&p[1]/960>.675f&&p[1]/960<.707f,"stock taps recorded meat row, not ad or close");
  r=new Runtime();w=r.expect("stock","103","103","stock-wait",PhaseEngine.CENTER);p=r.point(w,"103");check(p!=null&&p[1]/960>.64f&&p[1]/960<.70f,"shrinking stock dialog uses its relocated meat row "+Arrays.toString(p));
  r=new Runtime();w=r.expect("shop-customers","2","2","arrival-wait",PhaseEngine.CENTER);p=r.point(w,"2");check(w.id.equals(P+"customer-tap")&&p!=null&&p[0]/428<.35f&&p[1]/960<.45f,"only first confirmed rabbit's own face centre");
  r=new Runtime();w=r.expect("shop","121","123","shop-customers",PhaseEngine.WAIT);r.e.finish(w,1500);w=r.expect("shop-customers","121","123","work-opening",PhaseEngine.CENTER);p=r.point(w,"123");check(p!=null&&p[1]/960>.77f&&p[1]/960<.80f,"after shelves and customers press Baito");r.e.finish(w,1500);check(!ShoppingPreset.playable(r.e,r.last),"baito delivery does not prove warehouse entered");w=r.expect("work-opening","124","153","main",PhaseEngine.WAIT);r.e.finish(w,1500);check(ShoppingPreset.playable(r.e,r.last),"returned warehouse pixels enable marker");
  r=new Runtime();check(r.event("arrival","43","89")==null,"automatic rabbit celebration has no guessed claim button");w=r.expect("arrival","94","99","arrival-wait",PhaseEngine.CENTER);p=r.point(w,"99");check(p!=null&&p[1]/960>.53f&&p[1]/960<.56f,"manual rabbit reward uses coin claim button");
  for(String[] row:new String[][]{{"shift","4",".63",".67"},{"summon","120",".53",".56"},{"boost","176",".60",".64"}}){r=new Runtime();w=r.expect(row[0],row[1],row[1],"reward-ad",PhaseEngine.CENTER);p=r.point(w,row[1]);check(p!=null&&p[1]/960>Float.parseFloat(row[2])&&p[1]/960<Float.parseFloat(row[3]),"each dialog has its own yes centre: "+row[0]);}
 }
 static void missions(){
  Runtime r=new Runtime();PhaseEngine.Watch w=r.expect("missions","141","207","claim-wait",PhaseEngine.CENTER);float[] p=r.point(w,"207");check(w.id.equals(P+"get-tap")&&p!=null&&p[1]/960>.397f&&p[1]/960<.426f,"Get dominates Play and taps this reward's own row "+Arrays.toString(p));check(!ShoppingPreset.playable(r.e,r.last),"mission screen forbids transport taps");
  VirtualPresetProfileTest.Image im=frames.get("141-native");List<PhaseEngine.Region> plan=ScanPlan.select(r.e,w.regionId,false);check(plan.size()==2,"Get preflight includes heading");Map<String,float[]> fresh=r.layout.sample(plan,im.width,im.height,im,2000);check(r.e.confirmsAction(w,r.e.current,r.e.epoch,fresh),"native orange Get");fresh=r.layout.sample(plan,im.width,im.height,sized("238",im.width,im.height),2350);check(!r.e.confirmsAction(w,r.e.current,r.e.epoch,fresh),"dim mission overlay cannot authorize Get");
  r=new Runtime();r.expect("claim-wait","24","24","mission-ad",PhaseEngine.CENTER);w=r.expect("mission-ad","24","24","mission-ad",PhaseEngine.CENTER);check(w.regionId.equals(AdCloseAutomaton.RIGHT),"mission close preserves pending work");w=r.expect("claim-wait","152","152","reward",PhaseEngine.WAIT);w=r.expect("reward","152","152","mission-opening",PhaseEngine.CENTER);p=r.point(w,"152");check(p!=null&&p[1]/960>.55f&&p[1]/960<.58f,"Close is the actual reward centre");
  r.expect("mission-opening","137","208","missions",PhaseEngine.WAIT);w=r.expect("missions","137","208","mission-verify",PhaseEngine.CENTER);check(w.id.equals(P+"mission-play"),"Play only when no Get");r.e.finish(w,1500);check(!ShoppingPreset.playable(r.e,r.last),"Play must be followed by confirmed warehouse");w=r.expect("mission-verify","153","240","main",PhaseEngine.WAIT);r.e.finish(w,1500);check(ShoppingPreset.playable(r.e,r.last),"warehouse resumed after mission Play");
  for(String state:new String[]{"mission-opening","mission-ad","claim-wait"}){r=new Runtime();r.expect(state,"153","198","mission-tap",PhaseEngine.WAIT);check(ShoppingPreset.recoveryTarget(P+state).equals(P+"mission-opening"),"intent does not forget unfinished mission");}
  r=new Runtime();w=r.expect("mission-tap","153","198","mission-opening",PhaseEngine.CENTER);p=r.point(w,"198");check(p!=null&&p[0]/428>.70f&&p[0]/428<.87f&&p[1]/960>.06f&&p[1]/960<.09f,"mission tap uses actual header button");
  // Move the recorded first orange button to each of the other visible rows.
  final VirtualPresetProfileTest.Image get=im,play=frames.get("137-native");final int width=im.width,height=im.height;final int[] source=RegionMath.bounds(new float[]{.68f,.387f,.92f,.433f},width,height);
  for(float shift:new float[]{.182f,.364f}){RegionSampler.Pixels moved=(x,y)->{int py=y-Math.round(shift*height);if(x>=source[0]&&x<source[2]&&py>=source[1]&&py<source[3])return get.get(x,py);return play.get(x,y);};r=new Runtime();r.e.enter(P+"missions",0);fresh=r.layout.sample(r.e.activeRegions(),width,height,moved,1000);r.e.observe(fresh,1000);check(r.e.poll()==null,"moved Get requires two frames");fresh=r.layout.sample(r.e.activeRegions(),width,height,moved,1350);r.e.observe(fresh,1350);w=r.e.poll();check(w!=null&&w.id.equals(P+"get-tap"),"second/third row Get blocks first Play");p=r.layout.point(w,fresh,width,height);check(p!=null&&Math.abs(p[1]/height-(.410f+shift))<.012f,"tap centre belongs to the individually located Get row");}
 }
 static void adsAndNegatives(){
  for(String frame:new String[]{"24","30","49","24-native"}){Runtime r=new Runtime();PhaseEngine.Watch w=r.expect("ad",frame,frame,"ad",PhaseEngine.CENTER);float[] p=r.point(w,frame);VirtualPresetProfileTest.Image im=frames.get(frame);check(p!=null&&p[0]/im.width>.90f&&p[0]/im.width<.96f&&p[1]/im.height>.09f&&p[1]/im.height<.13f,"grey next at actual location including black margin: "+frame);}
  for(String frame:new String[]{"8","9","10","19","20","21","22","109","149","77","79","85","96","101","111","117","172","174","200","213","215","224","226","232"}){Runtime r=new Runtime();PhaseEngine.Watch w=r.event("ad",frame,frame);check(w==null||w.action==PhaseEngine.CENTER&&AdCloseAutomaton.handles(w.regionId),"foreign/ad/install/countdown never becomes a game action: "+frame);if(w!=null)check(!frame.equals("8")&&!frame.equals("9")&&!frame.equals("19")&&!frame.equals("20")&&!frame.equals("21")&&!frame.equals("22")&&!frame.equals("109"),"countdown must not match ready chevrons: "+frame);check(!ShoppingPreset.playable(r.e,r.last),"no marker on ad or Android home");}
  for(String frame:new String[]{"3","63","94","120","137","141","152","176","238","239"}){Runtime r=new Runtime();r.e.enter(P+"main",0);r.sample(frame,1000);check(!ShoppingPreset.playable(r.e,r.last),"covered/different scene blocks markers immediately: "+frame);}
  Runtime r=new Runtime();r.e.enter(P+"main",0);r.sample("236",1000);check(!r.last.containsKey(P+"boost-ready"+AdaptiveLayout.BOUNDS),"active boost timer blocks repeated boost ads");
  Runtime stable=new Runtime();stable.e.enter(P+"main",0);long now=1000;
  for(int n:new int[]{153,154,155,156,157,161,162,163,164,165,166,167,168,169,170,171,175,177,178,179,180,181,182,183,184,185,188,189,190,191,192,193,194,195,196,197,198,199,202,203,204,205,209,210,211,212,216,217,218,219,220,221,222,223,228,229,230,234,235,236,240}){now+=350;stable.sample(Integer.toString(n),now);check(ShoppingPreset.playable(stable.e,stable.last),"moving banknotes and changed counts remain warehouse: "+n);}

 }
 static void coordinatesAndOwnership(){
  VirtualPresetProfileTest.Image im=frames.get("198-native");for(float[] t:new float[][]{{1,1,0,0},{1,.90f,0,.06f},{.94f,.86f,.03f,.08f}}){Runtime r=new Runtime();r.e.enter(P+"verify",0);final int width=642,height=1440;RegionSampler.Pixels inset=(x,y)->{float sx=(x/(float)width-t[2])/t[0],sy=(y/(float)height-t[3])/t[1];if(sx<0||sx>=1||sy<0||sy>=1)return 0xff111820;return im.get(Math.min(im.width-1,(int)(sx*im.width)),Math.min(im.height-1,(int)(sy*im.height)));};Map<String,float[]> samples=r.layout.sample(r.e.activeRegions(),width,height,inset,1000);r.e.observe(samples,1000);check(r.e.poll()==null,"inset requires second frame");samples=r.layout.sample(r.e.activeRegions(),width,height,inset,1350);r.e.observe(samples,1350);PhaseEngine.Watch w=r.e.poll();check(w!=null&&w.nextPhase.equals(P+"main"),"same warehouse at normal/virtual inset "+Arrays.toString(t)+" "+r.e.diagnostic);r.e.finish(w,1500);float[] p=samples.get(AdaptiveLayout.MAIN);check(p!=null&&Math.abs(p[0]/width-(.5f*t[0]+t[2]))<.02f&&Math.abs(p[1]/height-(ShoppingPreset.MAIN_Y*t[1]+t[3]))<.02f,"default marker follows this sampled window");}
  PhaseEngine e=new PhaseEngine();ShoppingPreset.install(e,refs);check(!ShoppingPreset.install(e,refs),"no duplicate default graph");PhaseEngine custom=e.runtimeCopy();custom.regions.get(P+"home").bounds[0]+=.01f;check(AdaptiveLayout.install(custom,ShoppingPreset.APP,refs,Collections.emptyMap())==null,"custom coordinate edits preserved");check(PresetRegistry.supports(ShoppingPreset.APP)&&PresetRegistry.asset(ShoppingPreset.APP).equals("shopping-preset.json"),"all app selectors use same package and asset");
  for(PhaseEngine.Phase state:e.phases.values()){check(state.markersDuring==state.id.equals(P+"main"),"only warehouse authorizes markers");for(PhaseEngine.Watch w:state.watches){check(w.waitMs==0&&w.historyRule.isEmpty()&&w.historyPhase.isEmpty(),"no fixed confirmation delay or hidden history");}}
  for(String state:new String[]{"main","shop","shop-customers","stock","arrival"}){e.enter(P+state,0);for(PhaseEngine.Region roi:e.activeRegions()){check(!AdCloseAutomaton.handles(roi.id)||(roi.bounds[2]-roi.bounds[0])*(roi.bounds[3]-roi.bounds[1])<=.019f,"ad interruption corners remain sparse");check((roi.bounds[2]-roi.bounds[0])*(roi.bounds[3]-roi.bounds[1])<.03f,"declared ordinary ROI remains small");}}
 }
 public static void main(String[] args)throws Exception{load();scenes();shop();missions();adsAndNegatives();coordinatesAndOwnership();System.out.println("Video6666ReplayTest: "+checks+" checks passed; shop/warehouse, stock/customers, shift/summon/boost, missions/Get/Close/Play, ads/countdown, native/holdout pixels and synthetic insets/individual rows; real Android input not tested");}
}
